// region Verification functions

bool HasBalancedBrackets(
  const std::wstring& text
) {
  int depth = 0;

  for (const wchar_t character : text) {
    if (character == L'[') {
      ++depth;
    } else if (character == L']') {
      --depth;
      if (depth < 0) {
        return false;
      }
    }
  }

  return depth == 0;
}

bool TextsAreUnique(
  const std::vector<std::wstring>& texts
) {
  std::set<std::wstring> text_set;

  for (const std::wstring& text : texts) {
    if (text_set.find(text) != text_set.end()) {
      return false;
    }

    text_set.insert(text);
  }

  return true;
}

bool ItemsHaveUniqueLabels(
  const std::vector<
    std::shared_ptr<types::IItem>
  >& items
) {
  std::set<std::wstring> label_set;

  for (const std::shared_ptr<types::IItem>& item : items) {
    const std::wstring& label = item->label();

    if (label_set.find(label) != label_set.end()) {
      return false;
    }

    label_set.insert(label);
  }

  return true;
}

